// ==================== CALLBACK ДЛЯ A2DP ====================
int32_t get_sound_data(uint8_t* data, int32_t len) {
    if (!is_playing || audio_pos >= audio_size) {
        memset(data, 0, len);
        return len;
    }
    size_t remaining = audio_size - audio_pos;
    size_t to_copy = (remaining < (size_t)len) ? remaining : (size_t)len;
    memcpy(data, audio_buffer + audio_pos, to_copy);
    audio_pos += to_copy;
    if (to_copy < (size_t)len) {
        memset(data + to_copy, 0, len - to_copy);
    }
    if (audio_pos >= audio_size) {
        is_playing = false;
    }
    return len;
}

// ==================== URL-КОДИРОВАНИЕ ====================
String urlencode(String str) {
    String encoded = "";
    char c;
    char code[4];
    for (int i = 0; i < str.length(); i++) {
        c = str.charAt(i);
        if (isalnum(c)) {
            encoded += c;
        } else if (c == ' ') {
            encoded += '+';
        } else {
            sprintf(code, "%%%02X", c);
            encoded += code;
        }
    }
    return encoded;
}

// ==================== ЗАПРОС К DEEPSEEK НАПРЯМУЮ ====================
String ask_deepseek(String user_text) {
    HTTPClient http;
    http.begin("https://api.deepseek.com/chat/completions");
    http.addHeader("Content-Type", "application/json");
    http.addHeader("Authorization", "Bearer " + get_api_key());

    // Формируем JSON-запрос вручную
    String payload = "{\"model\":\"deepseek-chat\",\"messages\":["
                     "{\"role\":\"system\",\"content\":\"Ты полезный ассистент. Отвечай кратко на русском.\"},"
                     "{\"role\":\"user\",\"content\":\"" + user_text + "\"}"
                     "],\"max_tokens\":300}";

    int httpCode = http.POST(payload);
    String result = "";

    if (httpCode == HTTP_CODE_OK) {
        String response = http.getString();
        // Парсим JSON
        DynamicJsonDocument doc(4096);
        DeserializationError err = deserializeJson(doc, response);
        if (!err) {
            result = doc["choices"][0]["message"]["content"].as<String>();
        } else {
            Serial.println("JSON parse error: " + String(err.c_str()));
        }
    } else {
        Serial.printf("DeepSeek HTTP error: %d\n", httpCode);
    }
    http.end();
    return result;
}

// ==================== ПОЛУЧЕНИЕ TTS ====================
bool fetch_tts(String text) {
    HTTPClient http;
    String url = "http://translate.google.com/translate_tts?ie=UTF-8&q=" + urlencode(text) + "&tl=ru&client=tw-ob";
    http.begin(url);
    int httpCode = http.GET();
    if (httpCode == HTTP_CODE_OK) {
        int len = http.getSize();
        if (len > 0) {
            if (audio_buffer) { free(audio_buffer); audio_buffer = NULL; }
            audio_buffer = (uint8_t*)malloc(len);
            if (!audio_buffer) { http.end(); return false; }
            WiFiClient* stream = http.getStreamPtr();
            size_t bytesRead = 0;
            while (http.connected() && bytesRead < (size_t)len) {
                size_t available = stream->available();
                if (available) {
                    bytesRead += stream->readBytes(audio_buffer + bytesRead, available);
                }
                delay(1);
            }
            audio_size = bytesRead;
            audio_pos = 0;
            is_playing = true;
            Serial.printf("TTS: получено %d байт\n", audio_size);
            http.end();
            return true;
        }
    }
    Serial.printf("TTS error: %d\n", httpCode);
    http.end();
    return false;
}

