    server.send(200, "text/html",
        "<html><head><meta charset='UTF-8'></head><body>"
        "<h1>Обработка...</h1><p>" + user_text + "</p>"
        "<a href='/'>Назад</a></body></html>");

    String ai_response = ask_deepseek(user_text);
    Serial.println("Ответ: " + ai_response);
    if (ai_response.length() == 0) return;

    if (fetch_tts(ai_response)) {
        Serial.println("Играем...");
    }
}

